    if (ct === 'supporter') return !(window._pbPlayedThisTurn && window._pbPlayedThisTurn.supporter) && !_auraAgainst('noOppSupporter', player) && !_supporterLocked(player) && _trainerCondition(db, player);
    if (ct === 'item')      return !_itemLocked(player) && _trainerCondition(db, player);
