  // Miniatura de la PRÓXIMA energía (debajo de la zona de energía): muestra el tipo ya decidido.
  function _renderNextEnergy(player) {
    const zone = document.getElementById('energy-zone-' + player);
    if (!zone) return;
    const ty = window._pbNextEnergy && window._pbNextEnergy[player];
    let mini = document.getElementById('next-energy-' + player);
    if (!ty) { if (mini) mini.style.display = 'none'; return; }
    if (!mini) { mini = document.createElement('div'); mini.id = 'next-energy-' + player; mini.className = 'next-energy-mini ne-' + player; zone.appendChild(mini); }
    mini.style.display = '';
    mini.title = T('board.nextEnergy');
    const col = ORB_COLORS[ty] || ORB_COLORS.colorless;
    const iconSrc = (window.ORB_ICONS && window.ORB_ICONS[ORB_ICON_KEY[ty]]) || (window.ENERGY_ICONS && window.ENERGY_ICONS[ORB_ICON_KEY[ty]]);
    mini.style.setProperty('--ob', col.b); mini.style.setProperty('--od', col.d); mini.style.setProperty('--og', col.g);
    mini.innerHTML = iconSrc ? '<img src="' + iconSrc + '" draggable="false">' : '';
  }
  window._renderNextEnergy = _renderNextEnergy;

  // Crea el orbe de energía de la zona con su TIPO (arrastrable). Reutilizable: spawnOrb (animado)
