      p.style.background = expColors[i % expColors.length];
      const sz = 6 + Math.random() * 6;
      p.style.width = p.style.height = sz + 'px';
      p.style.margin = (-sz/2) + 'px';
      p.style.animationDuration = (0.38 + Math.random() * 0.22) + 's';
      p.style.animationDelay = (i * 8) + 'ms';
      zone.appendChild(p);
