        const _benchL = _benchedCards(_koPlayer).filter(function (c) { return !_ecOp.benchType || _isType(c, _ecOp.benchType); });
        const _nMove = Math.min(_ecOp.count || 0, _energyOrbsOf(card, [_ecOp.etype]).length, _benchL.length);
