        const koPlayer  = playerZoneId === 'zone-p1' ? 'p1' : 'p2';
        const opponent  = koPlayer === 'p1' ? 'p2' : 'p1';
        // On-KO: Fade into Darkness / Shattering Crystal pueden negar el punto (moneda).
        // Un KO puntúa UNA sola vez por carta en toda la partida. En online el mismo KO
        // puede intentar resolverse por dos caminos (el evento del rival y, si el tablero
        // se quedó a medias, el vigilante) y sobre elementos DISTINTOS tras un re-montaje
        // → sin este candado el marcador se desincronizaba (una pantalla 3-1 y la otra 2-1).
        const _koUid = _cardUid(card);
