          if (_isNormalMode() && (card._koSource || 'attack') === 'attack' && window._pbAttacker && _toolHas(window._pbAttacker, 'toolDrawOnKOgiven')) {
            const _lmN = (_toolOp(window._pbAttacker, 'toolDrawOnKOgiven').n) || 1;
            for (let _lm = 0; _lm < _lmN; _lm++) { window.drawOneCard && window.drawOneCard(opponent); }
          }
