  function toggleSound() {
    soundEnabled = !soundEnabled;
    const t = document.getElementById('sound-toggle');
    if (t) t.classList.toggle('on', soundEnabled);
  }

  // Toggle de efectos visuales (tilt / holo / autoRotate) desde Ajustes → window.PB_FX.
  window._toggleFx = function (name) {
    // auto-rotación depende del tilt: si el tilt está OFF, su fila está atenuada
    // y no se puede togglear.
    if (name === 'autoRotate' && !(window.pbFx && window.pbFx('tilt'))) return;
    // «ampliar en el centro» depende de que se amplíen las cartas
    if (name === 'peekCenter' && !(window.pbFx && window.pbFx('cardPeek'))) return;
    const on = !(window.pbFx && window.pbFx(name));
    if (window.pbSetFx) window.pbSetFx(name, on);
    const sw = document.getElementById('fx-' + name + '-switch');
    if (sw) sw.classList.toggle('on', on);
    if (name === 'tilt' || name === 'cardPeek') _syncFxDeps();
  };
  // Atenúa la fila de auto-rotación cuando el tilt 3D está apagado.
  function _syncFxDeps() {
    const tiltOn = !!(window.pbFx && window.pbFx('tilt'));
    const row = document.getElementById('fx-autoRotate-row');
    if (row) row.classList.toggle('sbs-disabled', !tiltOn);
    // «en el centro» solo tiene sentido si se amplían las cartas
    const peekOn = !!(window.pbFx && window.pbFx('cardPeek'));
    const prow = document.getElementById('fx-peekCenter-row');
    if (prow) prow.classList.toggle('sbs-disabled', !peekOn);
  }
  (function initFxSwitches() {
    ['tilt', 'holo', 'autoRotate', 'cardInfo', 'cardPeek', 'peekCenter', 'reduceMotion'].forEach(function (name) {
      const sw = document.getElementById('fx-' + name + '-switch');
      if (sw && window.pbFx) sw.classList.toggle('on', window.pbFx(name));
    });
    const st = document.getElementById('sound-toggle');
    if (st) st.classList.toggle('on', soundEnabled);
    _syncFxDeps();
  })();

