    window._pbMullAsked = { p1: false, p2: false };   // y vuelve a preguntarse al repartir
    window._pbAskClose && window._pbAskClose();       // y nunca queda una pregunta de la partida anterior
    window._pbExtraDraw = { p1: 0, p2: 0 };   // cartas extra del mulligan pendientes de ofrecer
    window._pbSetGameFormat(window._pbFormatFromDecks());   // marcador (3/4 puntos) según los mazos cargados
    window._pbLog = [];                       // registro de acciones: nueva partida = log limpio
    window._pbStatLog = [];                   // …y su acumulador de estadísticas
    window._pbCoinsWon = { p1: 0, p2: 0 };    // monedas ganadas por jugador (stats del Fin PvP)
    window._pbDelayed = [];                   // efectos retardados pendientes: limpios en nueva partida
    window._pbAfterPromote = [];              // 2º golpe del doble ataque pendiente de promoción: limpio
    window._pbKoSpread = 0;                   // reparto de energía on-KO a medias: limpio
    window._pbAfterPromotions = [];           // cierres de ataque esperando promoción: limpios
    window._pbAtkDeferKO = false;             // secuencia de ataque a medias: los KO vuelven a resolverse solos
    window._pbHpAnims = 0;
    // Maquinaria de KO/promoción/pendientes y locks: si un efecto quedó a medias, dejaba el tablero
