      _sourceDx = dx; _sourceDy = dy; _sourceSc = sc;

      _anims.forEach(a => a.cancel());
      _anims = [];
      flipper.style.transform  = '';
      zoomCard.style.transform = '';
      wrapper.style.transform  = '';
      wrapper.style.opacity    = '';
