      const HALF = 320;
      const DUR  = HALF * 2;
      const FS    = _zd.fs;                 // escala final en reposo (móvil 0.75)
      const midDX = dx + (TX - dx) * 0.08;  // 8% del camino hacia el destino
      const midDY = dy + (TY - dy) * 0.08 - 18;
      const midSC = sc + (FS - sc) * 0.12;

      const moveAnim = wrapper.animate([
        { transform: `translate(${dx}px,${dy}px) scale(${sc})`,         opacity: 0.6, offset: 0   },
        { transform: `translate(${midDX}px,${midDY}px) scale(${midSC})`,opacity: 1,   offset: 0.5 },
        { transform: `translate(${TX}px,${TY}px) scale(${FS})`,              opacity: 1,   offset: 1   }
      ], { duration: DUR, easing: 'cubic-bezier(0.4, 0, 0.2, 1)', fill: 'forwards' });

