          + (selected.size >= MAX_ENERGY_TYPES && !selected.has(type) ? ' disabled-toggle' : '');
        btn.title = type[0].toUpperCase() + type.slice(1);
        if (src) { const img = document.createElement('img'); img.src = src; img.draggable = false; btn.appendChild(img); }
        else btn.textContent = type[0].toUpperCase();
