  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => { initScale(); loadAll(); setTimeout(loadLegacyDeckPersist, 150); });
  } else {
    initScale(); loadAll(); setTimeout(loadLegacyDeckPersist, 150);
  }

  // ── Proportional scaling — entire page as one unit ──
  window._pageScale = 1;
  function initScale() {} // no scaling needed - CSS flexbox handles it


  // ══════════════════════════════════════════════════════════════════════
  // VER LA CARTA (pbCardPeek) — la carta que señalas, en GRANDE, sin abrir
  // el zoom ni bloquear el tablero.
  //   · PC    : al pasar el ratón por la mano y por las cartas en juego
  //             (modelo TCG Live: preview fija en el lateral libre).
