// ══════════════════════════════════════════════════════════════
// Sistema de rutas híbrido (100% local, sin red externa):
//  1. Cartas personalizadas (id empieza con "CU-") → tu carpeta local.
//  2. Cartas oficiales → si cards-view.js ya cargó su resolver
//     (window.cvCardImg / window.cvPlaceholderCard), lo reutiliza para
//     mantener un único criterio; si no, cae en un placeholder SVG local
//     con el color de tipo, nombre y set — nunca se pide nada a un
//     servidor de TCGmini.
// La versión anterior de esta función apuntaba a "https://tcgmini.com" +
// id + ".png", lo que hotlinkeaba/descargaba arte oficial sin permiso.
// Queda corregida: ningún camino de este archivo hace esa petición.
// ══════════════════════════════════════════════════════════════
const _CV_FALLBACK_TYPE_COLORS = {
  fire:'#ff5520', water:'#30a8ff', grass:'#38c030', lightning:'#ffe030',
  psychic:'#d050f0', fighting:'#c05818', darkness:'#3a3a48', metal:'#90b0c8',
  dragon:'#e6c73c', colorless:'#d8ceb0'
};
function _cvFallbackPlaceholder(card) {
  const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const type = (card && card.cardType) || 'colorless';
  const color = _CV_FALLBACK_TYPE_COLORS[type] || _CV_FALLBACK_TYPE_COLORS.colorless;
  const name = esc((card && card.name) || (card && card.id) || '?');
  const sub  = esc([(card && card.set) || '', (card && card.number) ? '#' + card.number : ''].filter(Boolean).join(' '));
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 420">'
    + '<rect width="300" height="420" rx="16" fill="#1a1a24"/>'
    + '<rect x="6" y="6" width="288" height="408" rx="12" fill="' + color + '55" stroke="' + color + '" stroke-width="3"/>'
    + '<text x="150" y="195" text-anchor="middle" font-family="sans-serif" font-size="20" font-weight="700" fill="#fff">' + name + '</text>'
    + (sub ? '<text x="150" y="222" text-anchor="middle" font-family="sans-serif" font-size="13" fill="#ffffffcc">' + sub + '</text>' : '')
    + '</svg>';
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
}
function getCardImageUrl(cardOrId) {
  const card = (cardOrId && typeof cardOrId === 'object') ? cardOrId : null;
  const id = card ? card.id : cardOrId;
  if (!id) return '';

  // 1. Cartas personalizadas: siempre tu carpeta local
  if (String(id).startsWith('CU-')) {
    return '../assets/cards/' + id + '.png';
  }

  // 2. Cartas oficiales: reutiliza el resolver de cards-view.js si está disponible
  //    (que ya descarta cualquier URL http(s) externa, incluida la del propio
  //    cards_db.js apuntando a GitHub, y usa solo rutas locales relativas)
  if (window.cvCardImg && card) return window.cvCardImg(card);

  // 3. Sin objeto de carta o sin cards-view.js cargado aún: placeholder local
  return _cvFallbackPlaceholder(card || { id: id });
}
window.getCardImageUrl = getCardImageUrl;
